Here is a simple implementation of a `Point` class in C++ that represents a point in two-dimensional space:

```cpp
#include <iostream>

class Point {
private:
    double x;
    double y;

public:
    // Constructor
    Point(double xVal = 0.0, double yVal = 0.0) : x(xVal), y(yVal) {}

    // Getter methods
    double getX() const { return x; }
    double getY() const { return y; }

    // Setter methods
    void setX(double xVal) { x = xVal; }
    void setY(double yVal) { y = yVal; }

    // Method to calculate distance from origin
    double distanceFromOrigin() const {
        return std::sqrt(x * x + y * y);
    }

    // Method to print the point
    void print() const {
        std::cout << "(" << x << ", " << y << ")" << std::endl;
    }
};

int main() {
    Point p1(3.0, 4.0);
    p1.print(); // Output: (3, 4)
    std::cout << "Distance from origin: " << p1.distanceFromOrigin() << std::endl;

    return 0;
}
```

This class includes:
- Private members for `x` and `y` coordinates.
- A constructor with default values.
- Getter and setter methods.
- A method to calculate the Euclidean distance from the origin.
- A method to display the point's coordinates.
